public class ContactTriggerHandler {
    public static void handleBefore(List<Contact> contacts, Boolean isInsert) {
        // Collect all unique AccountIds from contacts
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // Query all relevant accounts in one SOQL
        Map<Id, Account> accountMap = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource 
            FROM Account 
            WHERE Id IN :accountIds
        ]);

        // Apply logic to each contact
        for (Contact c : contacts) {
            if (c.AccountId != null && accountMap.containsKey(c.AccountId)) {
                Account a = accountMap.get(c.AccountId);
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (isInsert && String.isBlank(c.LeadSource)) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    public static void handleAfter(List<Contact> contacts) {
        // Collect contacts with AccountId and Phone (non-blank)
        Map<Id, Contact> firstContactWithPhoneByAccount = new Map<Id, Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                if (!firstContactWithPhoneByAccount.containsKey(c.AccountId)) {
                    firstContactWithPhoneByAccount.put(c.AccountId, c);
                    accountIds.add(c.AccountId);
                }
            }
        }

        // Query accounts to check their current Phone
        Map<Id, Account> accountMap = new Map<Id, Account>([
            SELECT Id, Phone 
            FROM Account 
            WHERE Id IN :accountIds
        ]);

        // Prepare accounts to update
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            Account a = accountMap.get(accountId);
            Contact firstContact = firstContactWithPhoneByAccount.get(accountId);
            if (String.isBlank(a.Phone)) {
                a.Phone = firstContact.Phone;
                accountsToUpdate.add(a);
            }
        }

        // Update accounts in one DML statement
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
