public class PaymentTerms {
    public static Integer parseNetDays(String terms) {
        // Keep original terms for error message
        String originalTerms = terms;

        // If terms is null, throw UnsupportedTermsException
        if (terms == null) {
            throw new UnsupportedTermsException('Unsupported payment terms: null');
        }

        // Trim and convert to lowercase for processing
        String trimmedLower = terms.trim().toLowerCase();

        // Check for "due on receipt"
        if (trimmedLower == 'due on receipt') {
            return 0;
        }

        // Check for NET pattern
        Pattern netPattern = Pattern.compile('net\\s*\\d{1,3}');
        Matcher matcher = netPattern.matcher(trimmedLower);
        if (matcher.matches()) {
            String matched = matcher.group();
            String digits = matched.replaceAll('[^0-9]', '');
            Integer netDays = Integer.valueOf(digits);
            if (netDays > 180) {
                throw new TermsOutOfRangeException('Net days out of range: ' + netDays);
            }
            return netDays;
        }

        // If nothing matched, throw UnsupportedTermsException with original terms
        throw new UnsupportedTermsException('Unsupported payment terms: ' + originalTerms);
    }

    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        return invoiceDate.addDays(netDays);
    }
}
