public class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        // Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200');
        }

        // Validate fields
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields cannot be null or empty');
        }

        // Validate objectApiName
        if (string.isBlank(objectApiName)) {
            throw new SearchException('objectApiName cannot be blank');
        }

        // Get SObjectType (case-insensitive)
        String normalizedObjectApiName = objectApiName.toLowerCase();
        Map<String, SObjectType> globalDescribe = Schema.getGlobalDescribe();
        if (!globalDescribe.containsKey(normalizedObjectApiName)) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        SObjectType sObjectType = globalDescribe.get(normalizedObjectApiName);

        // Check user can read the object
        if (!sObjectType.getDescribe().isAccessible()) {
            throw new SearchException('Running user cannot read object: ' + objectApiName);
        }

        // Validate and normalize fields
        List<String> normalizedFields = new List<String>();
        Map<String, DescribeFieldResult> fieldDescribeMap = new Map<String, DescribeFieldResult>();
        for (String field : fields) {
            if (string.isBlank(field)) {
                throw new SearchException('Field name cannot be blank: ' + field);
            }
            String normalizedField = field.toLowerCase();
            DescribeFieldResult describeField = sObjectType.getDescribe().fields.getMap().get(normalizedField);
            if (describeField == null) {
                throw new SearchException('Field does not exist: ' + field);
            }
            if (!describeField.isAccessible()) {
                throw new SearchException('Running user cannot read field: ' + field);
            }
            normalizedFields.add(describeField.getApiName()); // Use actual API name (case-correct)
            fieldDescribeMap.put(normalizedField, describeField);
        }

        // Validate filters
        Map<String, Object> normalizedFilters = new Map<String, Object>();
        if (filters != null) {
            for (String filterField : filters.keySet()) {
                if (string.isBlank(filterField)) {
                    throw new SearchException('Filter field name cannot be blank');
                }
                String normalizedFilterField = filterField.toLowerCase();
                DescribeFieldResult describeField = fieldDescribeMap.get(normalizedFilterField);
                if (describeField == null) {
                    // Check if the filter field is a field on the object (even if not in the fields list)
                    DescribeFieldResult filterFieldDescribe = sObjectType.getDescribe().fields.getMap().get(normalizedFilterField);
                    if (filterFieldDescribe == null) {
                        throw new SearchException('Filter field does not exist: ' + filterField);
                    }
                    describeField = filterFieldDescribe;
                }
                if (!describeField.isAccessible()) {
                    throw new SearchException('Running user cannot read filter field: ' + filterField);
                }
                if (!describeField.isFilterable()) {
                    throw new SearchException('Filter field cannot be filtered: ' + filterField);
                }
                normalizedFilters.put(normalizedFilterField, filters.get(filterField));
            }
        }

        // Validate orderByField
        String normalizedOrderByField = null;
        if (!string.isBlank(orderByField)) {
            String normalizedOrderBy = orderByField.toLowerCase();
            DescribeFieldResult orderByDescribe = sObjectType.getDescribe().fields.getMap().get(normalizedOrderBy);
            if (orderByDescribe == null) {
                throw new SearchException('Order-by field does not exist: ' + orderByField);
            }
            if (!orderByDescribe.isSortable()) {
                throw new SearchException('Order-by field cannot be sorted: ' + orderByField);
            }
            if (!orderByDescribe.isAccessible()) {
                throw new SearchException('Running user cannot read order-by field: ' + orderByField);
            }
            normalizedOrderByField = orderByDescribe.getApiName();
        }

        // Build SOQL query
        String selectClause = 'SELECT Id';
        if (!normalizedFields.isEmpty()) {
            selectClause += ',' + String.join(normalizedFields, ',');
        }

        String whereClause = '';
        List<Object> bindValues = new List<Object>();
        if (normalizedFilters != null && !normalizedFilters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String filterField : normalizedFilters.keySet()) {
                Object filterValue = normalizedFilters.get(filterField);
                conditions.add(filterField + ' = :bindValue');
                bindValues.add(filterValue);
            }
            whereClause = 'WHERE ' + String.join(conditions, ' AND ');
        }

        String orderByClause = '';
        if (normalizedOrderByField != null) {
            orderByClause = 'ORDER BY ' + normalizedOrderByField + ' ASC';
        }

        String soql = selectClause + ' FROM ' + sObjectType.getDescribe().getName() + 
                      whereClause + 
                      orderByClause + 
                      ' LIMIT ' + maxRows;

        // Execute query
        List<SObject> results = Database.query(soql, bindValues);
        return results;
    }
}
