public class ContactLookupAction {

    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;
        @InvocableVariable
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        // Collect unique normalized emails from requests
        Set<String> normalizedEmails = new Set<String>();
        Map<String, Request> requestMap = new Map<String, Request>();

        for (Request req : requests) {
            String normalizedEmail = normalizeEmail(req.email);
            if (normalizedEmail != null) {
                normalizedEmails.add(normalizedEmail);
                requestMap.put(normalizedEmail, req);
            }
        }

        // Query contacts for the normalized emails
        Map<String, List<Contact>> contactsByEmail = new Map<String, List<Contact>>();
        if (normalizedEmails.size() > 0) {
            List<Contact> contacts = [SELECT Id, Email, CreatedDate 
                                      FROM Contact 
                                      WHERE Email IN :normalizedEmails];

            // Group contacts by normalized email
            for (Contact c : contacts) {
                String normalizedEmail = normalizeEmail(c.Email);
                if (!contactsByEmail.containsKey(normalizedEmail)) {
                    contactsByEmail.put(normalizedEmail, new List<Contact>());
                }
                contactsByEmail.get(normalizedEmail).add(c);
            }
        }

        // Process each request
        for (Request req : requests) {
            Result result = new Result();
            String normalizedEmail = normalizeEmail(req.email);

            if (normalizedEmail == null) {
                result.found = false;
                result.contactId = null;
            } else if (!contactsByEmail.containsKey(normalizedEmail)) {
                result.found = false;
                result.contactId = null;
            } else {
                // Get the contact with the earliest CreatedDate
                List<Contact> contactList = contactsByEmail.get(normalizedEmail);
                Contact earliestContact = contactList[0];
                for (Contact c : contactList) {
                    if (c.CreatedDate < earliestContact.CreatedDate) {
                        earliestContact = c;
                    }
                }
                result.found = true;
                result.contactId = earliestContact.Id;
            }
            results.add(result);
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (email == null || email.trim() == '') {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
