            event.Order_Number__c = shipment.orderNumber;
            event.Tracking_Number__c = shipment.trackingNumber;
            event.Carrier__c = shipment.carrier;
            events.add(event);
        }

        if (events.isEmpty()) {
            return 0;
        }

        List<PlatformEventPublisher.PublishResult> results = PlatformEventPublisher.publish(events);
        Integer successCount = 0;
        for (PlatformEventPublisher.PublishResult result : results) {
            if (result.success) {
                successCount++;
            }
        }

        return successCount;
    }
