public class Opportunities extends fflib_SObjectDomain {
    private Set<Id> qualifyingOpportunityIds = new Set<Id>();

    public Opportunities(fflib_SObjectDomain.IConstructable constructor) {
        super(constructor);
    }

    public static fflib_SObjectDomain.IConstructable newConstructor() {
        return new Constructor();
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct() {
            return new Opportunities(this);
        }
    }

    public void onInsert(List<Opportunity> newOpps) {
        for (Opportunity opp : newOpps) {
            if (opp.StageName == 'Closed Won') {
                qualifyingOpportunityIds.add(opp.Id);
            }
        }
    }

    public void onUpdate(Map<Id, Opportunity> newOpps, Map<Id, Opportunity> oldOpps) {
        for (Id oppId : newOpps.keySet()) {
            Opportunity newOpp = newOpps.get(oppId);
            Opportunity oldOpp = oldOpps.get(oppId);
            if (newOpp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                qualifyingOpportunityIds.add(oppId);
            }
        }
    }

    protected override void execute(fflib_SObjectDomain.SObjectDomainEvent event) {
        super.execute(event);
        processFulfilment();
    }

    private void processFulfilment() {
        if (!qualifyingOpportunityIds.isEmpty()) {
            IOpportunityFulfilmentService service = (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingOpportunityIds);
        }
        qualifyingOpportunityIds.clear();
    }
}
