public with sharing class Opportunities extends fflib_SObjectDomain
{
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct()
        {
            return new Opportunities();
        }
    }

    @Override
    public void validate()
    {
        // Rule 1: Amount cannot be negative on insert or update
        for (Opportunity opp : getRecords())
        {
            if (opp.Amount < 0)
            {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }

        // Rule 2: On update, if stage was already Closed Won, Amount cannot change
        // This rule only applies to updates where the old stage was Closed Won
        if (isUpdate())
        {
            Map<Id, Opportunity> oldMap = getOldMap();
            for (Opportunity opp : getRecords())
            {
                Opportunity oldOpp = oldMap.get(opp.Id);
                if (oldOpp != null && oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount)
                {
                    error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }
    }
}
