            newTask.ActivityDate = Date.today().addDays(7);
            newTask.Status = 'Not Started';
            newTask.Priority = 'Normal';

            tasksToInsert.add(newTask);
        }

        // Insert tasks individually with try/catch to handle validation failures
        for (Task task : tasksToInsert) {
            try {
                insert task;
            } catch (DmlException e) {
                // Find the opportunity ID associated with this task
                Id oppId = task.WhatId;
                failedOpportunityIds.add(oppId);
            }
