public with sharing class LeadContactMatcher {
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();

        for (Lead lead : leads) {
            // Normalize lead email: trim and convert to lowercase
            String leadEmail = lead.Email;
            if (String.isBlank(leadEmail)) {
                // Blank email never matches
                result.add(null);
                continue;
            }
            leadEmail = leadEmail.trim().toLowerCase();

            Id matchedContactId = null;
            for (Contact contact : contacts) {
                // Normalize contact email: trim and convert to lowercase
                String contactEmail = contact.Email;
                if (String.isBlank(contactEmail)) {
                    // Blank contact email, skip this contact
                    continue;
                }
                contactEmail = contactEmail.trim().toLowerCase();

                if (leadEmail == contactEmail) {
                    matchedContactId = contact.Id;
                    break; // Found first match in contacts order
                }
            }
            result.add(matchedContactId);
        }

        return result;
    }
}
```

