    Map<String, Id> emailToContactId = new Map<String, Id>();
    for (Contact contact : contacts) {
        if (!String.isBlank(contact.Email)) {
            String key = contact.Email.trim().toLowerCase();
            // Only store first contact for each email (as per requirement)
            if (!emailToContactId.containsKey(key)) {
                emailToContactId.put(key, contact.Id);
            }
        }
    }

    List<Id> result = new List<Id>();
    for (Lead lead : leads) {
        if (String.isBlank(lead.Email)) {
            result.add(null);
        } else {
            String key = lead.Email.trim().toLowerCase();
            result.add(emailToContactId.get(key));
        }
    }
    return result;
}
