trigger CaseTrigger on Case (after update) {
    // Map of old cases for comparison
    Map<Id, Case> oldCaseMap = Trigger.oldMap;

    // Collect IDs of cases that are newly closed and have a contact
    List<Id> caseIdsToProcess = new List<Id>();

    for (Case newCase : Trigger.new) {
        Case oldCase = oldCaseMap.get(newCase.Id);

        // Check if IsClosed changed from false to true
        if (oldCase != null && !oldCase.IsClosed && newCase.IsClosed) {
            // Check if the case has a contact
            if (newCase.ContactId != null) {
                caseIdsToProcess.add(newCase.Id);
            }
        }
    }

    // Enqueue a job for each case
    for (Id caseId : caseIdsToProcess) {
        System.enqueueJob(new CaseSurveyJob(caseId));
    }
}
