        const drafts = event.detail.draftValues;
        const promises = drafts.map(draft => {
            const recordInput = {
                fields: {
                    Id: draft.Id,
                    Title: draft.Title,
                    Phone: draft.Phone,
                    Email: draft.Email
                }
            };
            return updateRecord(recordInput);
        });

        Promise.all(promises)
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Contacts updated',
                        variant: 'success'
                    })
                );
                this.draftValues = [];
                // Refresh the wired data
                this.contacts.refresh();
