import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    @track waiting = null;
    @track longestWaitMinutes = null;
    @track error = null;

    private pollingInterval = null;
    private isFetching = false;
    private visibilityListener = null;

    connectedCallback() {
        // Initialize visibility state
        this.isVisible = document.visibilityState === 'visible';

        // Add visibility change listener
        this.visibilityListener = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this.visibilityListener);

        // Load stats immediately
        this.fetchStats();

        // Start polling every 60 seconds
        this.pollingInterval = setInterval(() => {
            if (this.isVisible && !this.isFetching) {
                this.fetchStats();
            }
        }, 60000);
    }

    disconnectedCallback() {
        // Clear polling interval
        if (this.pollingInterval) {
            clearInterval(this.pollingInterval);
            this.pollingInterval = null;
        }

        // Remove visibility change listener
        if (this.visibilityListener) {
            document.removeEventListener('visibilitychange', this.visibilityListener);
            this.visibilityListener = null;
        }
    }

    handleVisibilityChange() {
        this.isVisible = document.visibilityState === 'visible';

        // If page becomes visible, load stats immediately
        if (this.isVisible && !this.isFetching) {
            this.fetchStats();
        }
    }

    fetchStats() {
        if (this.isFetching) {
            // Skip if a request is already in flight
            return;
        }

        this.isFetching = true;

        getQueueStats()
            .then(result => {
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.error = null; // Clear error on successful refresh
            })
            .catch(error => {
                this.error = error.body.message;
            })
            .finally(() => {
                this.isFetching = false;
            });
    }
}
