import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];
    @api value = '';

    @track activeOptionId = '';
    @track listboxElement;

    connectedCallback() {
        this._updateActiveOption();
    }

    renderedCallback() {
        this.listboxElement = this.template.querySelector('ul[role="listbox"]');
        if (this.listboxElement) {
            this.listboxElement.setAttribute('aria-activedescendant', this.activeOptionId);
        }
    }

    _updateActiveOption() {
        if (this.options.length === 0) {
            this.activeOptionId = '';
            return;
        }

        if (this.value) {
            const selectedOption = this.options.find(opt => opt.value === this.value);
            if (selectedOption) {
                this.activeOptionId = `option-${selectedOption.value}`;
                return;
            }
        }

        // Default to first option if no value selected
        this.activeOptionId = `option-${this.options[0].value}`;
    }

    _handleKeyDown(event) {
        const key = event.key;
        const options = this.options;
        const activeId = this.activeOptionId;

        if (options.length === 0) {
            return;
        }

        // Find current active index
        let currentIndex = -1;
        for (let i = 0; i < options.length; i++) {
            if (`option-${options[i].value}` === activeId) {
                currentIndex = i;
                break;
            }
        }

        let newIndex = currentIndex;

        switch (key) {
            case 'ArrowDown':
                if (currentIndex < options.length - 1) {
                    newIndex = currentIndex + 1;
                }
                break;
            case 'ArrowUp':
                if (currentIndex > 0) {
                    newIndex = currentIndex - 1;
                }
                break;
            case 'Home':
                newIndex = 0;
                break;
            case 'End':
                newIndex = options.length - 1;
                break;
            case 'Enter':
            case ' ':
                // Select the active option
                const selectedOption = options[newIndex];
                if (selectedOption && selectedOption.value !== this.value) {
                    this.value = selectedOption.value;
                    this.dispatchEvent(new CustomEvent('change', {
                        detail: { value: this.value }
                    }));
                }
                event.preventDefault();
                return;
            default:
                // For all other keys (including Tab), do not prevent default
                return;
        }

        // Update active option without selecting
        if (newIndex !== currentIndex) {
            this.activeOptionId = `option-${options[newIndex].value}`;
        }

        // Prevent default for navigation keys
        if (key === 'ArrowDown' || key === 'ArrowUp' || key === 'Home' || key === 'End') {
            event.preventDefault();
        }
    }

    _handleOptionClick(event) {
        const optionElement = event.target;
        const value = optionElement.dataset.value;

        if (value !== this.value) {
            this.value = value;
            this.activeOptionId = `option-${value}`;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: this.value }
            }));
        }
    }
}
