public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        // Return empty list for null or empty input
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // Create NPSP Data Import records for each gift
        List<npsp__DataImport__c> dataImportRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c dataImport = new npsp__DataImport__c();
            dataImport.npsp__Contact1_Firstname__c = gift.firstName;
            dataImport.npsp__Contact1_Lastname__c = gift.lastName;
            dataImport.npsp__Contact1_Personal_Email__c = gift.email;
            dataImport.npsp__Donation_Amount__c = gift.amount;
            dataImport.npsp__Donation_Date__c = gift.giftDate;
            dataImportRecords.add(dataImport);
        }

        // Insert the data import records
        insert dataImportRecords;

        // Process the data imports using NPSP's DataImporter
        npsp__DataImporter.process(dataImportRecords);

        // Query the updated data import records to get import results
        List<npsp__DataImport__c> processedRecords = [
            SELECT Id, npsp__Status__c, npsp__Contact1__c, npsp__Donation__c, npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :dataImportRecords
        ];

        // Build ImportResult list in the same order as input
        List<ImportResult> results = new List<ImportResult>();
        for (WebGift gift : gifts) {
            // Find the corresponding data import record
            npsp__DataImport__c dataImport = null;
            for (npsp__DataImport__c rec : processedRecords) {
                // We need to match by the original values since we don't have a direct link
                // Instead, we'll use the order - processedRecords should be in same order as inserted
                // But to be safe, we can match by the fields we set
                if (rec.npsp__Contact1_Firstname__c == gift.firstName &&
                    rec.npsp__Contact1_Lastname__c == gift.lastName &&
                    rec.npsp__Contact1_Personal_Email__c == gift.email &&
                    rec.npsp__Donation_Amount__c == gift.amount &&
                    rec.npsp__Donation_Date__c == gift.giftDate) {
                    dataImport = rec;
                    break;
                }
            }

            // If we couldn't find a match (shouldn't happen), use the first unmatched record
            // Actually, since we inserted in order and process in order, we can use index matching
            // But the query doesn't preserve order. Let's use a different approach.

            // We'll create a map from the original dataImportRecords to the processed ones
            // Since we inserted dataImportRecords and then processed them, we can assume
            // the processedRecords list contains the same records but with updated fields.
            // We'll iterate through dataImportRecords and find the corresponding processed record.
        }

        // Better approach: Create a map from Id to processed record
        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>();
        for (npsp__DataImport__c rec : processedRecords) {
            processedMap.put(rec.Id, rec);
        }

        // Now for each original dataImport record, get the processed version
        for (npsp__DataImport__c originalDataImport : dataImportRecords) {
            npsp__DataImport__c processedDataImport = processedMap.get(originalDataImport.Id);
            ImportResult result = new ImportResult();

            // Check if import was successful
            if (processedDataImport.npsp__Status__c == 'Imported') {
                result.success = true;
                result.contactId = processedDataImport.npsp__Contact1__c;
                result.opportunityId = processedDataImport.npsp__Donation__c;
                result.errorMessage = null;
            } else {
                result.success = false;
                result.contactId = null;
                result.opportunityId = null;
                result.errorMessage = processedDataImport.npsp__FailureInformation__c;
            }

            results.add(result);
        }

        return results;
    }
}
