public class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // Validate input map
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('The percentage map must not be null or empty.');
        }

        // Validate percentages
        Decimal totalPercentage = 0;
        for (Decimal percent : percentByGauId.values()) {
            if (percent == null || percent <= 0) {
                throw new AllocationException('Each percentage must be greater than 0.');
            }
            totalPercentage += percent;
        }

        if (totalPercentage > 100) {
            throw new AllocationException('Total percentages cannot exceed 100%.');
        }

        // Get GAU IDs from the map
        List<Id> gauIds = new List<Id>(percentByGauId.keySet());

        // Query GAUs to check active status
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, npsp__Active__c FROM npsp__General_Accounting_Unit__c WHERE Id IN :gauIds]
        );

        // Validate GAU active status
        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);
            if (gau == null || !gau.npsp__Active__c) {
                throw new AllocationException('GAU ' + gauId + ' is inactive or does not exist.');
            }
        }

        // Delete existing allocations for the opportunity
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id FROM npsp__Allocation__c 
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // Create new allocations
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            npsp__Allocation__c allocation = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            );
            newAllocations.add(allocation);
        }

        // Insert new allocations
        insert newAllocations;

        return newAllocations;
    }
}
