public class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Validate all requests first
        validateRequests(requests);

        // Gather all unique opportunity IDs and contact IDs
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // Query opportunities to get amounts and primary contacts
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c 
             FROM Opportunity 
             WHERE Id IN :oppIds]
        );

        // Query existing OpportunityContactRoles for these contacts/opportunities
        Map<Id, OpportunityContactRole> ocrMap = new Map<Id, OpportunityContactRole>(
            [SELECT Id, OpportunityId, ContactId, Role 
             FROM OpportunityContactRole 
             WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds]
        );

        // Query existing partial soft credits
        Map<Id, npsp__Partial_Soft_Credit__c> partialSoftCreditMap = new Map<Id, npsp__Partial_Soft_Credit__c>(
            [SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
             FROM npsp__Partial_Soft_Credit__c
             WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds]
        );

        // Prepare lists for DML
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        List<npsp__Partial_Soft_Credit__c> partialSoftCreditsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> partialSoftCreditsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        // Process each request
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);

            // Find or create the OpportunityContactRole with the specified role
            OpportunityContactRole existingOcr = null;
            List<OpportunityContactRole> contactOcrs = new List<OpportunityContactRole>();

            // Get all OCRs for this contact on this opportunity
            for (OpportunityContactRole ocr : ocrMap.values()) {
                if (ocr.OpportunityId == req.opportunityId && ocr.ContactId == req.contactId) {
                    contactOcrs.add(ocr);
                }
            }

            // Check if there's an OCR with the exact role
            for (OpportunityContactRole ocr : contactOcrs) {
                if (ocr.Role == req.role) {
                    existingOcr = ocr;
                    break;
                }
            }

            if (existingOcr == null) {
                // Create a new OCR
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToInsert.add(newOcr);
                existingOcr = newOcr; // Use this for the soft credit
            } else {
                // Update the existing OCR if role is different
                if (existingOcr.Role != req.role) {
                    existingOcr.Role = req.role;
                    ocrsToUpdate.add(existingOcr);
                }
            }

            // Delete any other OCRs for this contact on this opportunity (except the one we're keeping)
            for (OpportunityContactRole ocr : contactOcrs) {
                if (ocr != existingOcr) {
                    ocrsToDelete.add(ocr);
                }
            }

            // Handle partial soft credit
            // Create a key for the partial soft credit map
            String key = req.opportunityId + '-' + req.contactId;
            npsp__Partial_Soft_Credit__c existingPartialSoftCredit = partialSoftCreditMap.get(key);

            if (existingPartialSoftCredit != null) {
                // Update existing partial soft credit
                existingPartialSoftCredit.npsp__Amount__c = req.amount;
                existingPartialSoftCredit.npsp__Role_Name__c = req.role;
                existingPartialSoftCredit.npsp__Contact_Role_ID__c = existingOcr.Id;
                partialSoftCreditsToUpdate.add(existingPartialSoftCredit);
            } else {
                // Create new partial soft credit
                npsp__Partial_Soft_Credit__c newPartialSoftCredit = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = existingOcr.Id
                );
                partialSoftCreditsToInsert.add(newPartialSoftCredit);
            }
        }

        // Perform DML operations
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }
        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }
        if (!partialSoftCreditsToInsert.isEmpty()) {
            insert partialSoftCreditsToInsert;
        }
        if (!partialSoftCreditsToUpdate.isEmpty()) {
            update partialSoftCreditsToUpdate;
        }
    }

    private static void validateRequests(List<SoftCreditRequest> requests) {
        // Get all opportunity IDs
        Set<Id> oppIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
        }

        // Query opportunities for validation
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c 
             FROM Opportunity 
             WHERE Id IN :oppIds]
        );

        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);

            // Check if amount is null, not positive, or greater than opportunity amount
            if (req.amount == null || req.amount <= 0 || req.amount > opp.Amount) {
                throw new SoftCreditException('Invalid amount for opportunity ' + req.opportunityId);
            }

            // Check if contact is the primary contact
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Contact ' + req.contactId + ' is the primary contact for opportunity ' + req.opportunityId);
            }
        }
    }
}
