public class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // Validate inputs
        if (contactId == null) {
            throw new IllegalArgumentException('Contact ID is required');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be positive');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required');
        }

        // Query the contact to verify it exists and get details
        Contact contact = [SELECT Id, FirstName, LastName, AccountId FROM Contact WHERE Id = :contactId LIMIT 1];
        if (contact == null) {
            throw new IllegalArgumentException('Contact does not exist');
        }

        // Get the household account
        Account householdAccount;
        if (contact.AccountId != null) {
            householdAccount = [SELECT Id FROM Account WHERE Id = :contact.AccountId LIMIT 1];
            if (householdAccount == null) {
                throw new IllegalArgumentException('Contact does not have a valid household account');
            }
        } else {
            throw new IllegalArgumentException('Contact does not have a household account');
        }

        // Create the opportunity
        Opportunity giftOpportunity = new Opportunity();
        giftOpportunity.Name = contact.FirstName + ' ' + contact.LastName + ' Donation ' + giftDate.format('yyyy-MM-dd');
        giftOpportunity.StageName = 'Closed Won';
        giftOpportunity.CloseDate = giftDate;
        giftOpportunity.Amount = amount;
        giftOpportunity.npsp__Primary_Contact__c = contact.Id;
        giftOpportunity.AccountId = householdAccount.Id;

        insert giftOpportunity;

        // Create contact roles
        List<OpportunityContactRole> contactRoles = new List<OpportunityContactRole>();

        // Primary contact role (Donor)
        OpportunityContactRole primaryRole = new OpportunityContactRole();
        primaryRole.ContactId = contact.Id;
        primaryRole.OpportunityId = giftOpportunity.Id;
        primaryRole.Role = 'Donor';
        primaryRole.IsPrimary = true;
        contactRoles.add(primaryRole);

        // Get all other contacts in the household
        List<Contact> householdContacts = [SELECT Id FROM Contact WHERE AccountId = :householdAccount.Id AND Id != :contact.Id];
        for (Contact householdContact : householdContacts) {
            OpportunityContactRole householdRole = new OpportunityContactRole();
            householdRole.ContactId = householdContact.Id;
            householdRole.OpportunityId = giftOpportunity.Id;
            householdRole.Role = 'Household Member';
            householdRole.IsPrimary = false;
            contactRoles.add(householdRole);
        }

        if (!contactRoles.isEmpty()) {
            insert contactRoles;
        }

        // Create payment - ensure no duplicate payments by checking existing payments
        List<npe01__OppPayment__c> existingPayments = [SELECT Id FROM npe01__OppPayment__c WHERE npe01__Opportunity__c = :giftOpportunity.Id];
        if (existingPayments.isEmpty()) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c();
            payment.npe01__Opportunity__c = giftOpportunity.Id;
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Scheduled_Date__c = giftDate;
            payment.npe01__Paid__c = true;

            insert payment;
        }

        return giftOpportunity.Id;
    }
}
