public class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Gather all contact IDs (children and parents)
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            contactIds.add(childId);
            contactIds.add(parentIdByChildId.get(childId));
        }

        // Query existing relationships involving these contacts
        List<npe4__Relationship__c> existingRelationships = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
               OR npe4__RelatedContact__c IN :contactIds
        ];

        // Build a set of pairs that already have a relationship
        Set<Pair> existingPairs = new Set<Pair>();
        for (npe4__Relationship__c rel : existingRelationships) {
            existingPairs.add(new Pair(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // Prepare list of new relationships to insert
        List<npe4__Relationship__c> newRelationships = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            // Check if this pair already exists in either direction
            Pair childToParent = new Pair(childId, parentId);
            Pair parentToChild = new Pair(parentId, childId);
            if (existingPairs.contains(childToParent) || existingPairs.contains(parentToChild)) {
                // Skip this pair
                continue;
            }
            // Create a new relationship from child's perspective
            npe4__Relationship__c rel = new npe4__Relationship__c();
            rel.npe4__Contact__c = childId;
            rel.npe4__RelatedContact__c = parentId;
            rel.npe4__Type__c = 'Parent';
            rel.npe4__Status__c = 'Current';
            // NPSP automatically creates the reciprocal relationship based on the parent's gender
            newRelationships.add(rel);
        }

        // Insert all new relationships
        if (!newRelationships.isEmpty()) {
            insert newRelationships;
        }
    }

    // Helper class to represent a pair of contact IDs (order-independent)
    private class Pair {
        Id first;
        Id second;

        Pair(Id f, Id s) {
            first = f;
            second = s;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return (first == pair.first && second == pair.second) ||
                   (first == pair.second && second == pair.first);
        }

        public Integer hashCode() {
            // Hash code that treats (a,b) and (b,a) as the same
            return first.hashCode() ^ second.hashCode();
        }
    }
}
