    public static List<FB_Employee__c> getDirectory() {
        // Check if the user can read the FB_Employee__c object
        if (!Schema.SObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Determine which fields the user can read
        Schema.SObjectField departmentField = FB_Employee__c.Department__c;
        Schema.SObjectField salaryField = FB_Employee__c.Salary__c;
        Schema.SObjectField personalEmailField = FB_Employee__c.Personal_Email__c;

        Boolean canReadDepartment = departmentField.isAccessible();
        Boolean canReadSalary = salaryField.isAccessible();
        Boolean canReadPersonalEmail = personalEmailField.isAccessible();

        // Build the SOQL query dynamically based on accessible fields
        String query = 'SELECT Id, Name';
        if (canReadDepartment) {
            query += ', Department__c';
        }
        if (canReadSalary) {
            query += ', Salary__c';
        }
        if (canReadPersonalEmail) {
            query += ', Personal_Email__c';
        }
        query += ' FROM FB_Employee__c ORDER BY Name ASC';

        // Execute the query and return the results
        return Database.query(query);
    }
}
