public with sharing class AccountOwnershipService {
    /**
     * Reassigns ownership of accounts and their contacts to a new owner.
     * Account trigger actions are bypassed during this operation.
     *
     * @param accountIds Set of Account IDs to reassign
     * @param newOwnerId ID of the new owner
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Bypass Account trigger actions for the entire transaction
        TriggerBase.bypass('Account');

        try {
            // Update Account ownership
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accountId : accountIds) {
                Account acc = new Account(Id = accountId, OwnerId = newOwnerId);
                accountsToUpdate.add(acc);
            }
            update accountsToUpdate;

            // Query all Contacts for these Accounts
            List<Contact> contactsToUpdate = [
                SELECT Id, AccountId 
                FROM Contact 
                WHERE AccountId IN :accountIds
            ];

            // Update Contact ownership
            for (Contact con : contactsToUpdate) {
                con.OwnerId = newOwnerId;
            }
            update contactsToUpdate;

        } finally {
            // Clear the bypass for Account triggers so automation behaves normally
            TriggerBase.clearBypass('Account');
        }
    }
}
