@IsTest
public class TA_Opportunity_GuardAmountDecreaseTest {

    private static final String ERROR_MESSAGE = TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE;

    @IsTest
    public static void test_ReductionMoreThanHalf() {
        // Behavior 1: reduction of more than half (1000 to 499) is rejected with exactly one error
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = new Opportunity(Id = fakeId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = fakeId, Amount = 499);

        List<Opportunity> triggerOld = new List<Opportunity>{oldOpp};
        List<Opportunity> triggerNew = new List<Opportunity>{newOpp};

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);

        System.assert(newOpp.hasErrors(), 'Expected error on opportunity with reduction more than half');
        System.assertEquals(1, newOpp.getErrors().size(), 'Expected exactly one error');
        System.assertEquals(ERROR_MESSAGE, newOpp.getErrors()[0].getMessage(), 'Error message mismatch');
    }

    @IsTest
    public static void test_ReductionExactlyHalf() {
        // Behavior 2: reduction of exactly half (1000 to 500) is accepted (no error)
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = new Opportunity(Id = fakeId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = fakeId, Amount = 500);

        List<Opportunity> triggerOld = new List<Opportunity>{oldOpp};
        List<Opportunity> triggerNew = new List<Opportunity>{newOpp};

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);

        System.assert(!newOpp.hasErrors(), 'Expected no error on opportunity with reduction exactly half');
    }

    @IsTest
    public static void test_Increase() {
        // Behavior 3: an increase is accepted
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = new Opportunity(Id = fakeId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = fakeId, Amount = 1500);

        List<Opportunity> triggerOld = new List<Opportunity>{oldOpp};
        List<Opportunity> triggerNew = new List<Opportunity>{newOpp};

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);

        System.assert(!newOpp.hasErrors(), 'Expected no error on opportunity with increase');
    }

    @IsTest
    public static void test_PreviousAmountNull() {
        // Behavior 4: a record whose previous Amount was null is accepted without an exception
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldOpp = new Opportunity(Id = fakeId, Amount = null);
        Opportunity newOpp = new Opportunity(Id = fakeId, Amount = 500);

        List<Opportunity> triggerOld = new List<Opportunity>{oldOpp};
        List<Opportunity> triggerNew = new List<Opportunity>{newOpp};

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);

        System.assert(!newOpp.hasErrors(), 'Expected no error when previous Amount was null');
    }

    @IsTest
    public static void test_MultipleRecords() {
        // Behavior 5: one call with several records where only some break the rule
        Id fakeId1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id fakeId2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id fakeId3 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        // Record 1: reduction more than half (should get error)
        Opportunity oldOpp1 = new Opportunity(Id = fakeId1, Amount = 1000);
        Opportunity newOpp1 = new Opportunity(Id = fakeId1, Amount = 499);

        // Record 2: reduction exactly half (should not get error)
        Opportunity oldOpp2 = new Opportunity(Id = fakeId2, Amount = 1000);
        Opportunity newOpp2 = new Opportunity(Id = fakeId2, Amount = 500);

        // Record 3: increase (should not get error)
        Opportunity oldOpp3 = new Opportunity(Id = fakeId3, Amount = 1000);
        Opportunity newOpp3 = new Opportunity(Id = fakeId3, Amount = 1500);

        List<Opportunity> triggerOld = new List<Opportunity>{oldOpp1, oldOpp2, oldOpp3};
        List<Opportunity> triggerNew = new List<Opportunity>{newOpp1, newOpp2, newOpp3};

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);

        // Record 1 should have error
        System.assert(newOpp1.hasErrors(), 'Record 1 should have error');
        System.assertEquals(1, newOpp1.getErrors().size(), 'Record 1 should have exactly one error');
        System.assertEquals(ERROR_MESSAGE, newOpp1.getErrors()[0].getMessage(), 'Record 1 error message mismatch');

        // Record 2 should not have error
        System.assert(!newOpp2.hasErrors(), 'Record 2 should not have error');

        // Record 3 should not have error
        System.assert(!newOpp3.hasErrors(), 'Record 3 should not have error');
    }
}
