        TA_Contact_Queries queries = TA_Contact_Queries.getInstance();

        for (SObject contact : triggerNew) {
            Id accountId = (Id)contact.get('AccountId');

            if (accountId != null && queries.accountsById.containsKey(accountId)) {
                Account account = queries.accountsById.get(accountId);

                String mailingStreet = (String)contact.get('MailingStreet');
                String mailingCity = (String)contact.get('MailingCity');
                String mailingPostalCode = (String)contact.get('MailingPostalCode');
                String mailingCountry = (String)contact.get('MailingCountry');

                if (String.isBlank(mailingStreet) && String.isBlank(mailingCity) && 
                    String.isBlank(mailingPostalCode) && String.isBlank(mailingCountry)) {
                    contact.set('MailingStreet', account.BillingStreet);
                    contact.set('MailingCity', account.BillingCity);
                    contact.set('MailingPostalCode', account.BillingPostalCode);
                    contact.set('MailingCountry', account.BillingCountry);
                }
            }
        }
    }
}
